import React, { useState } from 'react';
import { Trash2, Archive, Plus, Users, BookOpen, MapPin, Play, X, Clock, RefreshCw, CheckCircle } from 'lucide-react';

const DepartmentCard = ({ deptName = "Information Systems", deptCode = "IS", deptId = 1, onGenerate }) => {
  // --- 1. UI STATE ---
  const [activeTab, setActiveTab] = useState("subjects"); // Replaces Radix Tabs
  const [activeYear, setActiveYear] = useState("1");

  // --- 2. CONFIGURATION STATE ---
  const [examDays, setExamDays] = useState(1);
  const [dates, setDates] = useState(['']);
  const [windowStart, setWindowStart] = useState("08:00");
  const [windowEnd, setWindowEnd] = useState("17:00");
  const [sectionCount, setSectionCount] = useState(1);

  const [proctorPref, setProctorPref] = useState("department");
  const [roomPref, setRoomPref] = useState("department");

  // --- 3. ENTITY STATE ---
  const [subjects, setSubjects] = useState({ 1: [], 2: [], 3: [], 4: [], 5: [] });
  const [newSub, setNewSub] = useState({ code: '', name: '', duration: 60 });

  const [proctors, setProctors] = useState([]); 
  const [currentProctorName, setCurrentProctorName] = useState("");
  const [tempAvail, setTempAvail] = useState({ date: '', start: '', end: '' });

  const [localRooms, setLocalRooms] = useState([]);
  const [newRoom, setNewRoom] = useState("");

  // --- HELPERS ---
  const updateDate = (index, value) => {
    const newDates = [...dates];
    newDates[index] = value;
    setDates(newDates);
  };

  const handleDayChange = (val) => {
    const num = Math.max(1, parseInt(val) || 0);
    setExamDays(num);
    setDates(new Array(num).fill(''));
  };

  const addSubject = () => {
    if (subjects[activeYear].length >= 30) return alert("STRICT LIMIT: Maximum 30 subjects.");
    if (!newSub.code || !newSub.name) return;
    const entry = { ...newSub, id: Date.now(), duration_mins: newSub.duration, status: 'active' };
    setSubjects({ ...subjects, [activeYear]: [...subjects[activeYear], entry] });
    setNewSub({ code: '', name: '', duration: 60 });
  };

  const toggleArchiveSubject = (id) => {
    setSubjects({
      ...subjects,
      [activeYear]: subjects[activeYear].map(s => s.id === id ? { ...s, status: s.status === 'active' ? 'archived' : 'active' } : s)
    });
  };

  const addProctor = () => {
    if (!currentProctorName) return;
    setProctors([...proctors, { id: Date.now(), name: currentProctorName, availability: [], assignedToday: false }]);
    setCurrentProctorName("");
  };

  const saveAvailability = (pId) => {
    if (!tempAvail.date || !tempAvail.start || !tempAvail.end) return alert("Fill all fields.");
    setProctors(proctors.map(p => p.id === pId ? { ...p, availability: [...p.availability, { ...tempAvail }] } : p));
    setTempAvail({ date: '', start: '', end: '' });
  };

  const addRoom = () => {
    if (!newRoom) return;
    setLocalRooms([...localRooms, { id: Date.now(), number: newRoom.toUpperCase() }]);
    setNewRoom("");
  };

  // --- SIMULATED GENERATOR (For Testing) ---
  const generateSchedule = () => {
    const activeSubjects = subjects[activeYear].filter(s => s.status === 'active');

    if (activeSubjects.length === 0) {
        return alert("Error: Add at least one active subject first.");
    }

    // Mock data based on your current inputs
    const mockResults = activeSubjects.map((s, i) => ({
        subject_code: s.code,
        subject_name: s.name,
        room_number: localRooms[0]?.number || "TBA",
        proctor_name: proctors[0]?.name || "Staff",
        exam_date: dates[0] || "2026-04-10",
        start_time: windowStart,
        end_time: "10:00",
        year_level: activeYear,
        section_label: "A",
        hasConflict: false
    }));

    onGenerate(mockResults, dates.filter(d => d !== ''));
  };

  return (
    <div className="max-w-4xl mx-auto bg-white rounded-3xl shadow-2xl border border-slate-200 overflow-hidden mb-12">

      {/* HEADER */}
      <div className="bg-slate-900 p-6 text-white flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-black uppercase tracking-tighter">{deptName}</h2>
          <p className="text-[10px] text-blue-400 font-bold tracking-[0.2em]">DEPT CODE: {deptCode}</p>
        </div>
        <button className="bg-white/10 px-4 py-2 rounded-xl text-[10px] font-black hover:bg-white/20 transition-all uppercase tracking-widest">
          Archive Dept
        </button>
      </div>

      {/* TAB NAVIGATION */}
      <div className="flex bg-slate-50 border-b border-slate-200 p-2 gap-2">
        {['subjects', 'proctors', 'rooms', 'generate'].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
              activeTab === tab 
              ? 'bg-white shadow-md text-blue-600 border border-slate-200' 
              : 'text-slate-400 hover:bg-slate-100'
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      <div className="p-8">
        {/* SUBJECTS VIEW */}
        {activeTab === 'subjects' && (
          <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center gap-3 bg-blue-50 p-4 rounded-2xl border border-blue-100">
              <select className="bg-white p-2 rounded-lg font-black text-xs border-none shadow-sm" value={activeYear} onChange={(e)=>setActiveYear(e.target.value)}>
                {[1,2,3,4,5].map(y => <option key={y} value={y}>YR {y}</option>)}
              </select>
              <input placeholder="CODE" className="w-24 p-2 rounded-lg border-none shadow-sm uppercase text-xs font-bold" value={newSub.code} onChange={(e)=>setNewSub({...newSub, code: e.target.value})}/>
              <input placeholder="SUBJECT NAME" className="flex-1 p-2 rounded-lg border-none shadow-sm text-xs font-bold" value={newSub.name} onChange={(e)=>setNewSub({...newSub, name: e.target.value})}/>
              <button onClick={addSubject} className="bg-blue-600 text-white p-2.5 rounded-xl hover:bg-blue-700 shadow-lg"><Plus size={20}/></button>
            </div>

            <div className="grid grid-cols-2 gap-3">
              {subjects[activeYear].map(sub => (
                <div key={sub.id} className={`flex justify-between items-center p-4 border rounded-2xl ${sub.status === 'archived' ? 'opacity-40 bg-slate-100' : 'bg-white shadow-sm'}`}>
                  <div>
                    <p className="font-black text-[10px] text-blue-600 uppercase">{sub.code}</p>
                    <p className="text-xs font-bold text-slate-700">{sub.name}</p>
                  </div>
                  <button onClick={()=>toggleArchiveSubject(sub.id)} className="text-slate-300 hover:text-amber-500"><Archive size={16}/></button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* PROCTORS VIEW */}
        {activeTab === 'proctors' && (
          <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex gap-3 p-4 bg-emerald-50 rounded-2xl border border-emerald-100">
              <input placeholder="FULL NAME" className="flex-1 p-2 rounded-lg border-none shadow-sm text-xs font-bold" value={currentProctorName} onChange={(e)=>setCurrentProctorName(e.target.value)}/>
              <button onClick={addProctor} className="bg-emerald-600 text-white px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg shadow-emerald-200">Add Proctor</button>
            </div>
            {proctors.map(p => (
              <div key={p.id} className="p-4 border border-slate-100 rounded-2xl bg-white shadow-sm">
                <p className="font-black text-sm text-slate-800 mb-4 uppercase">{p.name}</p>
                <div className="flex gap-2 items-center bg-slate-50 p-2 rounded-xl">
                    <input type="date" className="text-[10px] p-2 border rounded-lg font-bold" value={tempAvail.date} onChange={(e)=>setTempAvail({...tempAvail, date: e.target.value})}/>
                    <input type="time" className="text-[10px] p-2 border rounded-lg font-bold" value={tempAvail.start} onChange={(e)=>setTempAvail({...tempAvail, start: e.target.value})}/>
                    <button onClick={()=>saveAvailability(p.id)} className="bg-slate-900 text-white px-4 py-2 rounded-lg text-[10px] font-black uppercase ml-auto">Add Avail</button>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* ROOMS VIEW */}
        {activeTab === 'rooms' && (
          <div className="space-y-6 animate-in fade-in duration-500">
            <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex gap-3">
              <input placeholder="ROOM NUMBER" className="flex-1 p-2 rounded-lg border-none shadow-sm text-xs font-bold uppercase" value={newRoom} onChange={(e)=>setNewRoom(e.target.value)}/>
              <button onClick={addRoom} className="bg-amber-600 text-white px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest">Register</button>
            </div>
            <div className="flex flex-wrap gap-3">
              {localRooms.map(r => (
                <div key={r.id} className="bg-white border px-4 py-2 rounded-xl font-black text-xs flex items-center gap-3">
                  {r.number} <X size={14} className="text-slate-300 cursor-pointer hover:text-red-500" onClick={()=>setLocalRooms(localRooms.filter(x=>x.id!==r.id))}/>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* GENERATE VIEW */}
        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-[2rem] p-8 text-white animate-in zoom-in duration-300">
             <div className="grid grid-cols-2 gap-8">
                <div className="space-y-6">
                   <label className="text-[10px] font-black uppercase text-blue-400 tracking-[0.2em]">Exam Days</label>
                   <input type="number" value={examDays} onChange={(e)=>handleDayChange(e.target.value)} className="w-full bg-slate-800 border-none p-4 rounded-2xl text-2xl font-black outline-none"/>
                   <div className="space-y-2 max-h-40 overflow-y-auto pr-2">
                      {dates.map((d, i) => (
                        <input key={i} type="date" value={d} onChange={(e)=>updateDate(i, e.target.value)} className="w-full bg-slate-800/50 p-3 rounded-xl text-xs font-bold border border-slate-700"/>
                      ))}
                   </div>
                </div>
                <div className="space-y-6">
                    <div className="flex justify-between gap-4">
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-500 uppercase block mb-2">Start</label>
                            <input type="time" value={windowStart} onChange={(e)=>setWindowStart(e.target.value)} className="w-full bg-slate-800 p-3 rounded-xl text-xs font-black outline-none"/>
                        </div>
                        <div className="flex-1">
                            <label className="text-[10px] font-black text-slate-500 uppercase block mb-2">End</label>
                            <input type="time" value={windowEnd} onChange={(e)=>setWindowEnd(e.target.value)} className="w-full bg-slate-800 p-3 rounded-xl text-xs font-black outline-none"/>
                        </div>
                    </div>
                    <div className="pt-6 border-t border-slate-700">
                       <button onClick={generateSchedule} className="w-full bg-blue-600 hover:bg-blue-500 py-5 rounded-2xl font-black text-xs uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3">
                          <CheckCircle size={18}/> Run Conflict-Free Engine
                       </button>
                    </div>
                </div>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
